function solve(board) {
  const cell = pickCell(board);            // the only interesting decision
  if (cell === null) return true;          // no blanks left, we are done

  const [row, col] = cell;
  for (let d = 1; d <= 9; d++) {
    if (!isLegal(board, row, col, d)) continue;

    board[row][col] = d;                   // choose
    if (solve(board)) return true;         // explore
    board[row][col] = 0;                   // un-choose
  }

  return false;                            // every digit failed here
}

