// Better: the blank with the fewest legal digits remaining.
function mostConstrained(board) {
  let best = null, bestCount = 10;
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      if (board[r][c] !== 0) continue;
      const count = countLegalDigits(board, r, c);
      if (count < bestCount) { bestCount = count; best = [r, c]; }
      if (count === 1) return best;        // cannot do better than forced
    }
  }
  return best;
}
